    -- Load favorites from file
    local function LoadFavorites()
        if isfile and isfile(FAVORITES_FILE) then
            local success, data = pcall(function()
                return HttpService:JSONDecode(readfile(FAVORITES_FILE))
            end)
            if success and type(data) == "table" then
                FavoritesList = data
                return
            end
        end
        FavoritesList = DEFAULT_FAVORITES
    end
    
    -- Save favorites to file
    local function SaveFavorites()
        if writefile then
            pcall(function()
                writefile(FAVORITES_FILE, HttpService:JSONEncode(FavoritesList))
            end)
        end
    end
    
    -- Add user to favorites
    local function AddToFavorites(username, userId)
        -- Check if already in favorites
        for _, fav in ipairs(FavoritesList) do
            if fav.id == userId then
                Services.StarterGui:SetCore("SendNotification", {
                    Title = "Favorites",
                    Text = username .. " already in favorites!",
                    Duration = 3
                })
                return false
            end
        end
        
        -- Check limit
        if #FavoritesList >= MAX_FAVORITES then
            Services.StarterGui:SetCore("SendNotification", {
                Title = "Favorites",
                Text = "Max favorites reached (" .. MAX_FAVORITES .. ")",
                Duration = 3
            })
            return false
        end
        
        -- Add to list
        table.insert(FavoritesList, {name = username, id = userId})
        SaveFavorites()
        
        Services.StarterGui:SetCore("SendNotification", {
            Title = "Favorites",
            Text = "Added " .. username .. " to favorites!",
            Duration = 3
        })
        
        return true
    end
    
    -- Remove from favorites
    local function RemoveFavorite(userId)
        for i, fav in ipairs(FavoritesList) do
            if fav.id == userId then
                table.remove(FavoritesList, i)
                SaveFavorites()
                return true
            end
        end
        return false
    end
    
