    -- Backup original avatar
    local function BackupOriginalAvatar()
        if HasBackup or not LocalPlayer.Character then return end
        
        local char = LocalPlayer.Character
        OriginalAvatar = {
            CharacterAppearanceId = LocalPlayer.CharacterAppearanceId,
            BodyColors = LocalPlayer:GetBodyColors()
        }
        
        -- Save clothing items
        OriginalAvatar.Clothing = {}
        for _, item in ipairs(char:GetChildren()) do
            if item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") then
                table.insert(OriginalAvatar.Clothing, item:Clone())
            end
        end
        
        -- Save accessories
        OriginalAvatar.Accessories = {}
        for _, item in ipairs(char:GetChildren()) do
            if item:IsA("Accessory") then
                table.insert(OriginalAvatar.Accessories, item:Clone())
            end
        end
        
        HasBackup = true
    end
    
    -- Get user info from input
    local function GetUserInfo(input)
        -- Check if input is numeric (User ID)
        local userId = tonumber(input)
        if userId then
            -- It's a numeric ID
            pcall(function()
                local player = Players:GetPlayerByUserId(userId)
                if player then
                    return player.Name, userId
                end
            end)
            
            -- Try to get username from API
            local success, response = pcall(function()
                return game:HttpGet("https://users.roblox.com/v1/users/" .. userId)
            end)
            
            if success then
                local data = HttpService:JSONDecode(response)
                if data and data.name then
                    return data.name, userId
                end
            end
        else
            -- It's a username
            local success, response = pcall(function()
                return game:HttpGet("https://api.roblox.com/users/get-by-username?username=" .. input)
            end)
            
            if success then
                local data = HttpService:JSONDecode(response)
                if data and data.Id then
                    return data.Username, data.Id
                end
            end
        end
        
        return nil, nil
    end
    
    -- Clone avatar function with explosion effect
    local function CloneAvatar(userId, username)
        if not LocalPlayer.Character then
            Services.StarterGui:SetCore("SendNotification", {
                Title = "Error",
                Text = "No character found!",
                Duration = 3
            })
            return false
        end
        
        -- Backup original if not done
        if not HasBackup then
            BackupOriginalAvatar()
        end
        
        -- Create explosion effect at character position
        local rootPart = LocalPlayer.Character:FindFirstChild("HumanoidRootPart")
        if rootPart then
            CreateExplosionEffect(rootPart.Position)
        end
        
        -- Load character appearance
        local success = pcall(function()
            LocalPlayer.CharacterAppearanceId = userId
        end)
        
        if success then
            Services.StarterGui:SetCore("SendNotification", {
                Title = "SUCCESS!",
                Text = "Avatar cloned from " .. (username or "User") .. "!",
                Duration = 4,
                Icon = "rbxassetid://6723928012"
            })
            
            -- Wait a bit then respawn to apply changes
            task.wait(0.5)
            if LocalPlayer.Character then
                LocalPlayer.Character:BreakJoints()
            end
            
            return true
        else
            Services.StarterGui:SetCore("SendNotification", {
                Title = "ERROR",
                Text = "Failed to clone avatar!",
                Duration = 3
            })
            return false
        end
    end
    
    -- Reset to original avatar
    local function ResetToOriginal()
        if not HasBackup then
            Services.StarterGui:SetCore("SendNotification", {
                Title = "Info",
                Text = "No backup found!",
                Duration = 3
            })
            return
        end
        
        -- Apply original appearance
        LocalPlayer.CharacterAppearanceId = OriginalAvatar.CharacterAppearanceId
        
        -- Re-add original clothing and accessories
        if LocalPlayer.Character then
            local char = LocalPlayer.Character
            
            -- Remove current clothing
            for _, item in ipairs(char:GetChildren()) do
                if item:IsA("Shirt") or item:IsA("Pants") or item:IsA("ShirtGraphic") or item:IsA("Accessory") then
                    item:Destroy()
                end
            end
            
            -- Add back original items
            task.wait(1) -- Wait for character to load
            
            if char then
                for _, item in ipairs(OriginalAvatar.Clothing) do
                    local clone = item:Clone()
                    clone.Parent = char
                end
                
                for _, accessory in ipairs(OriginalAvatar.Accessories) do
                    local clone = accessory:Clone()
                    clone.Parent = char
                end
            end
        end
        
        Services.StarterGui:SetCore("SendNotification", {
            Title = "RESET",
            Text = "Avatar restored to original!",
            Duration = 3
        })
        
        HasBackup = false
    end
    
